#:property PublishAot=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar
// and count total Friday the 13ths in a full 400-year cycle.

// Earliest Friday the 13th starting from 0001-01-01
var date = new DateTime(1, 1, 13); // start checking the 13th of each month
while (date.DayOfWeek != DayOfWeek.Friday)
    date = date.AddMonths(1);

Console.WriteLine($"Earliest Friday the 13th: {date:yyyy-MM-dd} ({date:dddd})");

// Count Friday the 13ths in a full 400-year Gregorian cycle (years 1–400)
int count = 0;
var cycleStart = new DateTime(1, 1, 1);
var cycleEnd = new DateTime(401, 1, 1);

for (var d = new DateTime(1, 1, 13); d < cycleEnd; d = d.AddMonths(1))
{
    if (d.DayOfWeek == DayOfWeek.Friday)
        count++;
}

Console.WriteLine($"Friday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");

// Bonus: which day-of-week lands on the 13th most often?
var dayCount = new int[7];
for (var d = new DateTime(1, 1, 13); d < cycleEnd; d = d.AddMonths(1))
    dayCount[(int)d.DayOfWeek]++;

Console.WriteLine("\n13th-of-month frequency by day of week (400-year cycle):");
foreach (DayOfWeek dow in Enum.GetValues<DayOfWeek>())
    Console.WriteLine($"  {dow,-10} {dayCount[(int)dow],4}");

